#!/usr/bin/env python3
"""Strict BSD ``ar`` handling for the OCCT ``Standard_Type.cxx`` backport.

Why this module exists
----------------------
FloeCADKit's two OCCT static slices are merged ``ar`` archives produced by
Apple ``libtool -static``.  The reviewed OCCT repair changes exactly one
translation unit (``src/Standard/Standard_Type.cxx``).  Rebuilding all 47
toolkits merely to replace that object is expensive and would replace every
other object with newly built bytes.  Instead the repair is a *surgical
single-object reconstruction*: take the pinned upstream archive, replace the
one ``Standard_Type.cxx.o`` member with an object compiled from the exact
reviewed source, rebuild the symbol index, and prove that every other object
member is byte-identical to the pinned archive.

This module implements that archive surgery and its read-only verification.
It is deliberately strict:

* only the BSD ``ar`` layout emitted by Apple's toolchain is accepted;
* the archive must parse exactly to EOF, with a valid 60-byte header
  terminator on every member;
* exactly one symbol index member and exactly one target member are required;
* a rewritten archive keeps the member order and every non-index,
  non-target raw member record (header + payload + pad) byte-for-byte;
* the symbol index is regenerated by the pinned toolchain's ``ranlib`` and
  then its offsets are checked against the member starts;
* the index record header is normalised (mtime/uid/gid = 0, mode 100644) so
  the reconstruction is byte-for-byte deterministic for the same base
  archive and replacement object.

The module never writes to the input archive and never touches a live vendor
file: callers pass an explicit output path (bootstrap installs that file with
its own atomic rename after independent verification).

Python 3.8+, standard library only.
"""

from __future__ import annotations

import hashlib
import os
import shutil
import struct
import subprocess
import tempfile

MAGIC = b"!<arch>\n"
HEADER_SIZE = 60
HEADER_TERMINATOR = b"`\n"
INDEX_PREFIX = "__.SYMDEF"
_READ_CHUNK = 1024 * 1024


class ArchiveError(Exception):
    """Actionable archive parsing or reconstruction failure."""


class Member:
    """One parsed archive member.

    ``data`` is the complete member payload as stored (for BSD long names this
    includes the ``#1/<len>`` name area).  ``payload`` is the object bytes with
    that name area stripped.  ``pad`` is the single newline byte that follows
    an odd-sized member, or ``b""``.
    """

    __slots__ = ("offset", "header", "name_field", "name", "size", "data", "payload", "pad")

    def __init__(self, offset, header, name_field, name, size, data, payload, pad):
        self.offset = offset
        self.header = header
        self.name_field = name_field
        self.name = name
        self.size = size
        self.data = data
        self.payload = payload
        self.pad = pad

    @property
    def raw(self):
        return self.header + self.data + self.pad


def sha256_bytes(data):
    return hashlib.sha256(data).hexdigest()


def sha256_file(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(_READ_CHUNK), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _decode_ascii_field(raw, what, offset):
    try:
        return raw.decode("ascii")
    except UnicodeDecodeError:
        raise ArchiveError("non-ASCII %s at archive offset %d" % (what, offset))


def _split_name(raw_name, data, offset):
    """Return (real_name, payload) for a BSD/GNU-style member name."""
    if raw_name.startswith("#1/"):
        try:
            name_len = int(raw_name[3:])
        except ValueError:
            raise ArchiveError("invalid BSD long-name length %r at offset %d"
                               % (raw_name, offset))
        if name_len <= 0 or name_len > len(data):
            raise ArchiveError("BSD long name length %d is outside the member at offset %d"
                               % (name_len, offset))
        raw = data[:name_len]
        name = raw.rstrip(b"\x00").decode("latin-1")
        if not name:
            raise ArchiveError("empty member name at archive offset %d" % offset)
        return name, data[name_len:]
    if raw_name == "//":
        raise ArchiveError(
            "GNU long-name table ('//') is not used by the pinned Apple archives"
        )
    name = raw_name.rstrip("/")
    if not name:
        raise ArchiveError("empty member name at archive offset %d" % offset)
    return name, data


def read_archive(path):
    """Parse a BSD ``ar`` archive exactly; return the ordered Member list."""
    try:
        total = os.path.getsize(path)
    except OSError as exc:
        raise ArchiveError("cannot stat archive %s: %s" % (path, exc))
    if total < len(MAGIC) + HEADER_SIZE:
        raise ArchiveError("archive is too small to be a BSD ar file: %s" % path)
    members = []
    with open(path, "rb") as handle:
        magic = handle.read(len(MAGIC))
        if magic != MAGIC:
            raise ArchiveError("not a BSD ar archive (bad magic %r): %s"
                               % (magic, path))
        offset = len(MAGIC)
        while offset < total:
            header = handle.read(HEADER_SIZE)
            if len(header) != HEADER_SIZE:
                raise ArchiveError("truncated member header at offset %d in %s"
                                   % (offset, path))
            if header[58:60] != HEADER_TERMINATOR:
                raise ArchiveError("invalid member header terminator at offset %d in %s"
                                   % (offset, path))
            name_field = _decode_ascii_field(header[0:16], "member name", offset)
            raw_name = name_field.rstrip()
            size_field = _decode_ascii_field(header[48:58], "member size", offset).strip()
            try:
                size = int(size_field)
            except ValueError:
                raise ArchiveError("invalid member size %r at offset %d in %s"
                                   % (size_field, offset, path))
            if size < 0:
                raise ArchiveError("negative member size at offset %d in %s"
                                   % (offset, path))
            if offset + HEADER_SIZE + size > total:
                raise ArchiveError(
                    "member %r size %d exceeds the archive at offset %d in %s"
                    % (raw_name, size, offset, path)
                )
            data = handle.read(size)
            if len(data) != size:
                raise ArchiveError("truncated member %r at offset %d in %s"
                                   % (raw_name, offset, path))
            pad = b""
            if size % 2:
                pad = handle.read(1)
                if len(pad) != 1:
                    raise ArchiveError("missing alignment pad after member %r in %s"
                                       % (raw_name, path))
            name, payload = _split_name(raw_name, data, offset)
            members.append(Member(offset, header, name_field, name, size, data, payload, pad))
            offset += HEADER_SIZE + size + (size % 2)
        if offset != total:
            raise ArchiveError("archive %s did not end on a member boundary" % path)
    if not members:
        raise ArchiveError("archive contains no members: %s" % path)
    return members


def find_index(members):
    found = [m for m in members if m.name.startswith(INDEX_PREFIX)]
    if len(found) != 1:
        raise ArchiveError(
            "expected exactly one %s symbol index, found %d"
            % (INDEX_PREFIX, len(found))
        )
    return found[0]


def find_member(members, name):
    found = [m for m in members if m.name == name]
    if len(found) != 1:
        raise ArchiveError("expected exactly one %r member, found %d" % (name, len(found)))
    return found[0]


def archive_summary(members, target_name):
    """Return the digest set that pins member identity and order.

    ``nonTargetMembersDigestSha256`` covers every member except the symbol
    index and the replaced target: name, object payload size and object
    payload SHA-256, in archive order.  It is independent of member headers
    and of the symbol index, so it is the exact "every other object unchanged"
    invariant shared by the recipe, the receipt and read-only checks.
    """
    index = find_index(members)
    target = find_member(members, target_name)
    order = hashlib.sha256()
    for member in members:
        order.update(member.name.encode("latin-1"))
        order.update(b"\n")
    digest = hashlib.sha256()
    for member in members:
        if member is index or member is target:
            continue
        digest.update(member.name.encode("latin-1"))
        digest.update(b"\x00")
        digest.update(str(len(member.payload)).encode("ascii"))
        digest.update(b"\x00")
        digest.update(sha256_bytes(member.payload).encode("ascii"))
        digest.update(b"\n")
    return {
        "memberCount": len(members),
        "targetMemberName": target.name,
        "targetPayloadSize": len(target.payload),
        "targetPayloadSha256": sha256_bytes(target.payload),
        "indexMemberName": index.name,
        "indexMemberSize": index.size,
        "indexPayloadSize": len(index.payload),
        "indexPayloadSha256": sha256_bytes(index.payload),
        "memberOrderSha256": order.hexdigest(),
        "nonTargetMembersDigestSha256": digest.hexdigest(),
    }


def _record(name_field, name_area, payload, mtime=b"0", uid=b"0", gid=b"0", mode=b"100644"):
    """Build one BSD ar member record around ``payload``.

    ``name_field`` is the original 16-byte field.  ``name_area`` is the bytes
    stored at the start of ``data`` (the padded long name for ``#1/`` names,
    otherwise empty).  When the original header fields are passed through, the
    only changed byte range is the size field.
    """
    if isinstance(name_field, str):
        name_field = name_field.encode("latin-1")
    data = name_area + payload
    size = len(data)
    if len(name_field) != 16:
        raise ArchiveError("internal error: name field must be 16 bytes")
    for label, value, width in (("mtime", mtime, 12), ("uid", uid, 6),
                                ("gid", gid, 6), ("mode", mode, 8)):
        if len(value) > width:
            raise ArchiveError("internal error: %s field is too wide" % label)
    size_text = str(size).encode("ascii")
    if len(size_text) > 10:
        raise ArchiveError("member is too large for a BSD ar header: %d bytes" % size)
    header = (
        name_field
        + mtime.ljust(12)
        + uid.ljust(6)
        + gid.ljust(6)
        + mode.ljust(8)
        + size_text.ljust(10)
        + HEADER_TERMINATOR
    )
    return header + data + (b"\n" if size % 2 else b"")


def _target_name_area(target):
    """Return the stored name-area bytes for a parsed member."""
    return target.data[:target.size - len(target.payload)]


def _member_starts(members):
    return set(member.offset for member in members)


def parse_symbol_index(members):
    """Validate the Darwin ranlib table and every member offset it names.

    Darwin ``__.SYMDEF`` layout (little-endian): a 4-byte ranlib table byte
    count, then ``count/8`` pairs of ``(string index, member offset)``, then a
    4-byte string-table byte count and the string table.  Offsets are absolute
    file offsets.  Every offset must name a real member start.
    """
    index = find_index(members)
    data = index.payload
    if len(data) < 8:
        raise ArchiveError("symbol index is too small: %d bytes" % len(data))
    table_size = struct.unpack_from("<I", data, 0)[0]
    if table_size % 8 != 0:
        raise ArchiveError("symbol index table size %d is not a multiple of 8" % table_size)
    if 4 + table_size + 4 > len(data):
        raise ArchiveError("symbol index table extends past the member payload")
    string_size = struct.unpack_from("<I", data, 4 + table_size)[0]
    if 4 + table_size + 4 + string_size != len(data):
        raise ArchiveError(
            "symbol index layout mismatch (table %d, strings %d, payload %d)"
            % (table_size, string_size, len(data))
        )
    starts = _member_starts(members)
    entries = table_size // 8
    for row in range(entries):
        string_offset, member_offset = struct.unpack_from("<II", data, 4 + row * 8)
        if string_offset >= string_size:
            raise ArchiveError("symbol index string offset %d is out of range" % string_offset)
        if member_offset not in starts:
            raise ArchiveError(
                "symbol index member offset %d does not name a member start" % member_offset
            )
    return {
        "entryCount": entries,
        "tableSize": table_size,
        "stringTableSize": string_size,
    }


def verify_against_base(base_members, spliced_members, target_name, replacement_payload):
    """Prove that only the target object and the index changed.

    Returns a machine-readable report.  Raises ArchiveError on any structural
    or byte-identity violation.
    """
    if len(base_members) != len(spliced_members):
        raise ArchiveError("member count changed: %d -> %d"
                           % (len(base_members), len(spliced_members)))
    index_name = find_index(base_members).name
    base_target = find_member(base_members, target_name)
    spliced_target = find_member(spliced_members, target_name)
    other_payloads = 0
    normalized = b"0".ljust(12) + b"0".ljust(6) + b"0".ljust(6) + b"644".ljust(8)
    for base_member, spliced_member in zip(base_members, spliced_members):
        if base_member.name != spliced_member.name:
            raise ArchiveError("member order changed at offset %d: %r -> %r"
                               % (base_member.offset, base_member.name, spliced_member.name))
        if base_member.name == index_name:
            continue
        if base_member.size != spliced_member.size:
            if base_member is not base_target:
                raise ArchiveError("non-target member %r changed size"
                                   % base_member.name)
        if spliced_member.header[16:48] != normalized:
            raise ArchiveError("member %r header was not normalised"
                               % spliced_member.name)
        if spliced_member.header[58:60] != HEADER_TERMINATOR:
            raise ArchiveError("member %r header terminator changed"
                               % spliced_member.name)
        if base_member is base_target:
            if spliced_member.payload != replacement_payload:
                raise ArchiveError("target member payload does not match the replacement object")
            if len(spliced_member.payload) != len(replacement_payload):
                raise ArchiveError("target member payload size mismatch")
            continue
        if base_member.payload != spliced_member.payload:
            raise ArchiveError(
                "non-target member %r object payload changed" % base_member.name
            )
        other_payloads += 1
    if spliced_target.payload != replacement_payload:
        raise ArchiveError("target member payload does not match the replacement object")
    parse_symbol_index(spliced_members)
    return {
        "memberCount": len(spliced_members),
        "unchangedNonTargetMemberPayloads": other_payloads,
        "headerNormalised": True,
        "targetPayloadSize": len(spliced_target.payload),
        "targetPayloadSha256": sha256_bytes(spliced_target.payload),
        "indexPayloadSize": len(find_index(spliced_members).payload),
        "indexPayloadSha256": sha256_bytes(find_index(spliced_members).payload),
    }


def _write_indexless(path, members, index_name, target_name, replacement_payload):
    target = find_member(members, target_name)
    name_area = _target_name_area(target)
    with open(path, "wb") as out:
        out.write(MAGIC)
        for member in members:
            if member.name == index_name:
                continue
            if member.name == target_name:
                header = member.header
                out.write(_record(
                    member.name_field,
                    name_area,
                    replacement_payload,
                    mtime=header[16:28],
                    uid=header[28:34],
                    gid=header[34:40],
                    mode=header[40:48],
                ))
            else:
                out.write(member.raw)


def _run_ranlib(path, ranlib_path, timeout):
    try:
        result = subprocess.run(
            [ranlib_path, path],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=timeout,
        )
    except OSError as exc:
        raise ArchiveError("could not run ranlib %r: %s" % (ranlib_path, exc))
    except subprocess.TimeoutExpired:
        raise ArchiveError("ranlib timed out after %s seconds" % timeout)
    if result.returncode != 0:
        message = result.stderr.decode("utf-8", "replace").strip()
        raise ArchiveError("ranlib failed (exit %d): %s"
                           % (result.returncode, message[:500]))


def _assemble_final(output_path, base_members, index, index_payload,
                    target, target_name, replacement_payload):
    """Write the final archive with normalised member metadata.

    Payload bytes, member names, member order and padding are preserved.  All
    member headers are normalised to mtime/uid/gid 0 and mode 644 (the index
    keeps mode 100644), matching the actual reconstructed artifacts and making
    the output deterministic independent of the base archive's timestamps.
    """
    final_tmp = output_path + ".tmp"
    index_name_area = index.data[:index.size - len(index.payload)]
    with open(final_tmp, "wb") as out:
        out.write(MAGIC)
        out.write(_record(
            index.name_field,
            index_name_area,
            index_payload,
            mtime=b"0",
            uid=b"0",
            gid=b"0",
            mode=b"100644",
        ))
        for member in base_members:
            if member.name == index.name:
                continue
            name_area = member.data[:member.size - len(member.payload)]
            payload = replacement_payload if member.name == target_name else member.payload
            out.write(_record(
                member.name_field,
                name_area,
                payload,
                mtime=b"0",
                uid=b"0",
                gid=b"0",
                mode=b"644",
            ))
    os.replace(final_tmp, output_path)


def splice_member(base_members, target_name, replacement_payload, output_path,
                  ranlib_path="/usr/bin/ranlib", timeout=900,
                  index_provider=None):
    """Write a deterministic archive = base members with one object replaced.

    The caller owns ``output_path`` (bootstrap passes a private temporary
    path).  The function writes ``output_path + '.tmp'`` and atomically
    renames it, so a partial reconstruction is never presented as complete.

    ``index_provider`` is a test seam: a callable receiving the index-less
    archive path and returning the symbol-index payload bytes.  Production
    leaves it as ``None`` and regenerates the index with ``ranlib``.
    """
    index = find_index(base_members)
    target = find_member(base_members, target_name)
    if not replacement_payload:
        raise ArchiveError("replacement object payload is empty")
    out_dir = os.path.dirname(os.path.abspath(output_path))
    if not os.path.isdir(out_dir):
        raise ArchiveError("output directory does not exist: %s" % out_dir)
    work_dir = tempfile.mkdtemp(prefix=".floecad-splice-", dir=out_dir)
    try:
        indexless = os.path.join(work_dir, "without-index.a")
        _write_indexless(indexless, base_members, index.name, target_name,
                         replacement_payload)
        if index_provider is None:
            _run_ranlib(indexless, ranlib_path, timeout)
            regenerated = read_archive(indexless)
            index_payload = find_index(regenerated).payload
            parse_symbol_index(regenerated)
        else:
            index_payload = index_provider(indexless)
            if not isinstance(index_payload, bytes):
                raise ArchiveError("index provider did not return bytes")
        _assemble_final(output_path, base_members, index, index_payload,
                        target, target_name, replacement_payload)
        final_members = read_archive(output_path)
        report = verify_against_base(base_members, final_members, target_name,
                                     replacement_payload)
        report["archiveSize"] = os.path.getsize(output_path)
        report["archiveSha256"] = sha256_file(output_path)
        report["summary"] = archive_summary(final_members, target_name)
        report["symbolIndex"] = parse_symbol_index(final_members)
        return report
    finally:
        shutil.rmtree(work_dir, ignore_errors=True)


def _main(argv):
    import argparse
    import json

    parser = argparse.ArgumentParser(description="Inspect or verify a BSD ar slice.")
    sub = parser.add_subparsers(dest="command", required=True)
    inspect = sub.add_parser("inspect", help="print member summary and index statistics")
    inspect.add_argument("archive")
    inspect.add_argument("--target", default="Standard_Type.cxx.o")
    verify = sub.add_parser("verify", help="compare a splice result with its base")
    verify.add_argument("--base", required=True)
    verify.add_argument("--result", required=True)
    verify.add_argument("--target", default="Standard_Type.cxx.o")
    verify.add_argument("--replacement", required=True,
                        help="object payload that the result must contain")
    args = parser.parse_args(argv)

    if args.command == "inspect":
        members = read_archive(args.archive)
        print(json.dumps({
            "archive": args.archive,
            "summary": archive_summary(members, args.target),
            "symbolIndex": parse_symbol_index(members),
        }, indent=2, sort_keys=True))
        return 0

    base = read_archive(args.base)
    result = read_archive(args.result)
    with open(args.replacement, "rb") as handle:
        replacement = handle.read()
    print(json.dumps(verify_against_base(base, result, args.target, replacement),
                     indent=2, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(_main(None))
